import{RE_ADRESSE}from"./chunk-VB33RMAF.js";import{appel,serveur}from"./chunk-FBYJLYFB.js";import{lien}from"./chunk-MENTKLMX.js";var exportes=null;function textesExportes(){return exportes||(exportes=fetch(lien("assets/data/textes.json"),{cache:"no-cache"}).then(r=>r.ok?r.json():null).then(j=>j&&Array.isArray(j.pages)?j:null).catch(()=>null)),exportes}var adressePage=a=>typeof a=="string"&&a.length<=60&&RE_ADRESSE.test(a)?a:"";async function pagePubliee(adresse){let a=adressePage(adresse);if(!a)return{absente:!0,ailleurs:!1};if(serveur())try{return{page:(await appel("GET","/pages/"+a)).page}}catch(e){if(e.statut===404)return{absente:!0,ailleurs:!1}}let t=await textesExportes(),p=t&&t.pages.find(x=>x.adresse===a);return p?{page:p}:{absente:!0,ailleurs:!serveur()}}async function pagesPubliees(){if(serveur())try{return(await appel("GET","/pages")).pages||[]}catch{}let t=await textesExportes();return t?t.pages.map(p=>({adresse:p.adresse,titre:p.titre,version:p.version,publiee_le:p.publiee_le})):[]}var lienPage=adresse=>lien("page.html?p="+adresse);export{pagePubliee,pagesPubliees,lienPage};
